CREATE OR REPLACE FUNCTION public.indicadores_users() RETURNS TABLE(id uuid,full_name text,email text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,coalesce(nullif(p.full_name,''),p.email,'Usuário'),p.email FROM public.profiles p WHERE p.deleted_at IS NULL AND public.indicadores_role(auth.uid()) IS NOT NULL ORDER BY 2 $$;
REVOKE ALL ON FUNCTION public.indicadores_users() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_users() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.indicadores_guard_objective() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; IF TG_OP='UPDATE' AND (NEW.confidential IS DISTINCT FROM OLD.confidential OR NEW.allowed_user_ids IS DISTINCT FROM OLD.allowed_user_ids) AND public.indicadores_role(auth.uid()) IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Somente Admin define visibilidade.'; END IF; IF trim(NEW.title)='' THEN RAISE EXCEPTION 'Informe o objetivo.'; END IF; IF NEW.parent_id IS NOT NULL AND EXISTS(WITH RECURSIVE parents AS (SELECT id,parent_id FROM public.indicadores_objectives WHERE id=NEW.parent_id UNION SELECT o.id,o.parent_id FROM public.indicadores_objectives o JOIN parents p ON o.id=p.parent_id) SELECT 1 FROM parents WHERE id=NEW.id) THEN RAISE EXCEPTION 'O alinhamento não pode formar um ciclo.'; END IF; IF NEW.parent_id IS NOT NULL AND NOT public.indicadores_objective_visible(NEW.parent_id) THEN RAISE EXCEPTION 'Objetivo superior indisponível.'; END IF; IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.indicadores_objectives WHERE id=NEW.parent_id AND cycle_id IS NOT DISTINCT FROM NEW.cycle_id) THEN RAISE EXCEPTION 'Objetivos alinhados devem usar o mesmo ciclo.'; END IF; IF NEW.cycle_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_cycles WHERE id=NEW.cycle_id AND archived) THEN RAISE EXCEPTION 'O ciclo está arquivado.'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.indicadores_guard_metric() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; IF trim(NEW.title)='' OR NEW.initial_value=NEW.target_value THEN RAISE EXCEPTION 'Informe um nome e uma meta diferente do valor inicial.'; END IF; IF NEW.measure='binary' AND (NEW.initial_value<>0 OR NEW.target_value<>1 OR NEW.current_value NOT IN(0,1)) THEN RAISE EXCEPTION 'Marco usa Não feito (0) ou Feito (1).'; END IF; IF NEW.objective_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_objectives o JOIN public.indicadores_cycles c ON c.id=o.cycle_id WHERE o.id=NEW.objective_id AND c.archived) THEN RAISE EXCEPTION 'O ciclo está arquivado.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER indicadores_metric_guard BEFORE INSERT OR UPDATE ON public.indicadores_metrics FOR EACH ROW EXECUTE FUNCTION public.indicadores_guard_metric();
CREATE OR REPLACE FUNCTION public.indicadores_convert_kpi(_metric_id uuid,_cycle_id uuid,_title text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.indicadores_metrics; objective uuid; BEGIN IF coalesce(public.indicadores_role(auth.uid()),'') NOT IN('admin','editor') OR NOT coalesce(public.indicadores_metric_visible(_metric_id),false) THEN RAISE EXCEPTION 'Sem permissão.'; END IF; SELECT * INTO m FROM public.indicadores_metrics WHERE id=_metric_id AND kind='kpi' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'KPI indisponível.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.indicadores_cycles WHERE id=_cycle_id AND NOT archived) THEN RAISE EXCEPTION 'Selecione um ciclo ativo.'; END IF; INSERT INTO public.indicadores_objectives(title,cycle_id,responsible_id) VALUES(_title,_cycle_id,m.responsible_id) RETURNING id INTO objective; INSERT INTO public.indicadores_metrics(title,kind,objective_id,responsible_id,measure,initial_value,target_value,current_value,unit) VALUES(m.title,'kr',objective,m.responsible_id,m.measure,CASE WHEN m.current_value=m.target_value THEN m.initial_value ELSE m.current_value END,m.target_value,m.current_value,m.unit); RETURN objective; END $$;
REVOKE ALL ON FUNCTION public.indicadores_convert_kpi(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_convert_kpi(uuid,uuid,text) TO authenticated,service_role;